import{_ as e,o as a,c as o,ae as r}from"./chunks/framework.Bs_1Tt6f.js";const u=JSON.parse('{"title":"Pattern Library","description":"","frontmatter":{},"headers":[],"relativePath":"docs/pattern-library.md","filePath":"docs/pattern-library.md"}'),n={name:"docs/pattern-library.md"};function s(i,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="pattern-library" tabindex="-1">Pattern Library <a class="header-anchor" href="#pattern-library" aria-label="Permalink to &quot;Pattern Library&quot;">​</a></h1><p>The <strong>Patterns</strong> page is the one place for the notation vocabulary of your project: every pattern that occurs in the transcriptions, your equivalents tables or your annotations, shown with its code, its Ref ID, example images from your annotations, and notes.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li>A <strong>hierarchy</strong> of patterns, grouped first by melodic direction and then by how the notes are connected, so related shapes sit together.</li><li>Per pattern: the <strong>code</strong>, its <strong>label</strong>, its <strong>Ref ID</strong> from the equivalents tables, how often it occurs, and how many of your annotations show it. Open a pattern to see <strong>image examples</strong> cut from your manuscript annotations.</li><li>A search box (code, label or Ref ID) and a filter <em>only annotated</em>.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Label and describe</strong> a pattern: the label and notes are saved with your workspace.</li><li><strong>Add a pattern by hand</strong> for a shape that exists only on a scan and in no transcription. The code must contain a <code>*</code> (e.g. <code>*u</code> or <code>[*ud]</code>).</li><li><strong>Create code variants</strong>: derive a variant from a base shape with one of your <a href="./settings-and-data.html">custom signs</a>.</li><li><strong>Edit the MEI template</strong> of a pattern: the neume components used when patterns are exported as MEI.</li><li><strong>Configure the variant buttons</strong> (<em>snippet variants</em>): the classifier letters offered when you annotate a snippet — by default a–g, or your own list.</li></ul><p>Everything on this page is saved in the workspace and travels with your backups.</p>',7)])])}const y=e(n,[["render",s]]);export{u as __pageData,y as default};
